+            'a targeted reply — excluded from the coverage gate (gh-1061), informational only:');
+        unaddressable.forEach(function(t) {
+            lines.push('- ' + threadShortLabel(t, 48));
+        });
+    }
+    lines.push('');
+    lines.push('</details>');
+    return lines.join('\n');
+}
