            github_remove_label: function() { return '{}'; }
        }, {
            scm: runCaseScmStub(threads, comments)
        });
        var result = loaded.mod.action({
            ticket: { key: 'PROJ-123', fields: { labels: [] } },
            response: response,
            customParams: {}
        });
        return { result: result, comments: comments, moved: moved, removed: removed };
    }

